r="Barangay, municipality, province"'); ?></section><section class="activity-schedule-panel"><div class="activity-form-section-heading"><span class="activity-schedule-mark"><?=icon('calendar')?></span><div><h3>Schedule</h3><p>Set the full activity time.</p></div></div><div class="activity-fields-grid"><?php time_fields($r); ?></div></section></div></div><?php form_end('?page=activities','Save requirement'); ?></section></dialog><?php
